package com.nikola.algorithmvisualizer.algorithm;
import java.util.*; import org.springframework.stereotype.Service; import com.nikola.algorithmvisualizer.trace.*;
@Service public class MergeSortAlgorithm extends AbstractSortingAlgorithm {
 public String id(){return "merge";} public AlgorithmInfo info(){return new AlgorithmInfo(id(),"Merge Sort");} public List<MetricType> metricTypes(){return List.of(MetricType.COMPARISONS,MetricType.WRITES);}
 public VersionedAlgorithmTrace<EventData> execute(List<Integer> input){var a=items(input);var t=new TraceEventBuilder(MAX_EVENTS);sort(a,0,a.size()-1,t);if(a.size()==1)t.add(SemanticEventType.MARK_SORTED,"complete-merge",a,ranges(new SortedRange(0,0)),new MarkSortedData(0,0));return result(input,a,t);}
 private void sort(List<TraceItem>a,int l,int r,TraceEventBuilder t){if(l>=r)return;int m=(l+r)/2;t.add(SemanticEventType.SPLIT_RANGE,"split-range",a,List.of(),new MergeData(l,m,r,List.of()));sort(a,l,m,t);sort(a,m+1,r,t);merge(a,l,m,r,t);}
 private void merge(List<TraceItem>a,int l,int m,int r,TraceEventBuilder t){var left=new ArrayList<>(a.subList(l,m+1));var right=new ArrayList<>(a.subList(m+1,r+1));var buffer=new ArrayList<TraceItem>();t.add(SemanticEventType.BEGIN_MERGE,"begin-merge",a,List.of(),new MergeData(l,m,r,buffer));int i=0,j=0,k=l;while(i<left.size()&&j<right.size()){var pair=List.of(left.get(i),right.get(j));t.add(SemanticEventType.COMPARE,"compare-halves",a,List.of(),new CompareData(List.of(l+i,m+1+j),pair,compare(pair.get(0),pair.get(1))));TraceItem next=left.get(i).value()<=right.get(j).value()?left.get(i++):right.get(j++);buffer.add(next);t.add(SemanticEventType.BUFFER_MOVE,"move-to-buffer",a,List.of(),new MergeData(l,m,r,buffer));a.set(k,next);t.add(SemanticEventType.WRITE,"write-merged",a,List.of(),new WriteData(List.of(k++),List.of(next)));}while(i<left.size()){var x=left.get(i++);buffer.add(x);t.add(SemanticEventType.BUFFER_MOVE,"move-to-buffer",a,List.of(),new MergeData(l,m,r,buffer));a.set(k,x);t.add(SemanticEventType.WRITE,"write-merged",a,List.of(),new WriteData(List.of(k++),List.of(x)));}while(j<right.size()){var x=right.get(j++);buffer.add(x);t.add(SemanticEventType.BUFFER_MOVE,"move-to-buffer",a,List.of(),new MergeData(l,m,r,buffer));a.set(k,x);t.add(SemanticEventType.WRITE,"write-merged",a,List.of(),new WriteData(List.of(k++),List.of(x)));}t.add(SemanticEventType.COMPLETE_MERGE,"complete-merge",a,ranges(new SortedRange(l,r)),new MergeData(l,m,r,buffer));}
}
